PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS roles (role_id INTEGER PRIMARY KEY, role_name TEXT NOT NULL UNIQUE, description TEXT);
CREATE TABLE IF NOT EXISTS users (user_id INTEGER PRIMARY KEY AUTOINCREMENT, role_id INTEGER NOT NULL, full_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, phone TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE', created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (role_id) REFERENCES roles(role_id));
CREATE TABLE IF NOT EXISTS departments (department_id INTEGER PRIMARY KEY, department_name TEXT NOT NULL UNIQUE, description TEXT);
CREATE TABLE IF NOT EXISTS doctors (doctor_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE, department_id INTEGER NOT NULL, specialization TEXT NOT NULL, license_number TEXT UNIQUE, qualification TEXT, experience_years INTEGER DEFAULT 0, consultation_fee NUMERIC DEFAULT 0, availability_status TEXT DEFAULT 'AVAILABLE', created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(user_id), FOREIGN KEY (department_id) REFERENCES departments(department_id));
CREATE TABLE IF NOT EXISTS patients (patient_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE, date_of_birth TEXT, gender TEXT, blood_group TEXT, address TEXT, emergency_contact_name TEXT, emergency_contact_phone TEXT, FOREIGN KEY (user_id) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS wards (ward_id INTEGER PRIMARY KEY, ward_name TEXT NOT NULL, ward_type TEXT, floor INTEGER);
CREATE TABLE IF NOT EXISTS beds (bed_id INTEGER PRIMARY KEY, ward_id INTEGER NOT NULL, bed_number TEXT NOT NULL, bed_type TEXT, status TEXT DEFAULT 'AVAILABLE', UNIQUE (ward_id, bed_number), FOREIGN KEY (ward_id) REFERENCES wards(ward_id));
CREATE TABLE IF NOT EXISTS appointments (appointment_id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL, doctor_id INTEGER NOT NULL, department_id INTEGER NOT NULL, appointment_date TEXT NOT NULL, appointment_time TEXT NOT NULL, reason TEXT, status TEXT DEFAULT 'PENDING', created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (patient_id) REFERENCES patients(patient_id), FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id), FOREIGN KEY (department_id) REFERENCES departments(department_id));
CREATE TABLE IF NOT EXISTS emergency_cases (emergency_id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL, assigned_doctor_id INTEGER, assigned_bed_id INTEGER, arrival_time TEXT DEFAULT CURRENT_TIMESTAMP, priority TEXT NOT NULL, condition_description TEXT, status TEXT DEFAULT 'OPEN', FOREIGN KEY (patient_id) REFERENCES patients(patient_id), FOREIGN KEY (assigned_doctor_id) REFERENCES doctors(doctor_id), FOREIGN KEY (assigned_bed_id) REFERENCES beds(bed_id));
CREATE TABLE IF NOT EXISTS bills (bill_id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL, bill_date TEXT DEFAULT CURRENT_TIMESTAMP, subtotal NUMERIC NOT NULL DEFAULT 0, discount NUMERIC NOT NULL DEFAULT 0, tax NUMERIC NOT NULL DEFAULT 0, total_amount NUMERIC NOT NULL DEFAULT 0, payment_status TEXT DEFAULT 'PENDING', FOREIGN KEY (patient_id) REFERENCES patients(patient_id));
CREATE TABLE IF NOT EXISTS bill_items (bill_item_id INTEGER PRIMARY KEY AUTOINCREMENT, bill_id INTEGER NOT NULL, item_type TEXT NOT NULL, description TEXT, quantity INTEGER DEFAULT 1, unit_price NUMERIC DEFAULT 0, amount NUMERIC DEFAULT 0, FOREIGN KEY (bill_id) REFERENCES bills(bill_id));
CREATE TABLE IF NOT EXISTS payments (payment_id INTEGER PRIMARY KEY AUTOINCREMENT, bill_id INTEGER NOT NULL, amount NUMERIC NOT NULL, payment_method TEXT NOT NULL, payment_date TEXT DEFAULT CURRENT_TIMESTAMP, transaction_reference TEXT, status TEXT DEFAULT 'SUCCESS', FOREIGN KEY (bill_id) REFERENCES bills(bill_id));
CREATE TABLE IF NOT EXISTS medical_records (record_id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL, doctor_id INTEGER NOT NULL, appointment_id INTEGER, diagnosis TEXT, symptoms TEXT, treatment TEXT, notes TEXT, record_date TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (patient_id) REFERENCES patients(patient_id), FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id), FOREIGN KEY (appointment_id) REFERENCES appointments(appointment_id));
CREATE TABLE IF NOT EXISTS prescriptions (prescription_id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL, doctor_id INTEGER NOT NULL, appointment_id INTEGER, prescription_date TEXT DEFAULT CURRENT_TIMESTAMP, instructions TEXT, FOREIGN KEY (patient_id) REFERENCES patients(patient_id), FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id), FOREIGN KEY (appointment_id) REFERENCES appointments(appointment_id));
CREATE TABLE IF NOT EXISTS prescription_items (prescription_item_id INTEGER PRIMARY KEY AUTOINCREMENT, prescription_id INTEGER NOT NULL, medicine_id INTEGER NOT NULL, dosage TEXT, frequency TEXT, duration TEXT, instructions TEXT, FOREIGN KEY (prescription_id) REFERENCES prescriptions(prescription_id), FOREIGN KEY (medicine_id) REFERENCES medicines(medicine_id));
CREATE TABLE IF NOT EXISTS lab_reports (report_id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL, doctor_id INTEGER, appointment_id INTEGER, test_name TEXT NOT NULL, test_date TEXT NOT NULL, result TEXT, status TEXT DEFAULT 'PENDING', remarks TEXT, FOREIGN KEY (patient_id) REFERENCES patients(patient_id), FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id), FOREIGN KEY (appointment_id) REFERENCES appointments(appointment_id));
CREATE TABLE IF NOT EXISTS medicines (medicine_id INTEGER PRIMARY KEY AUTOINCREMENT, medicine_name TEXT NOT NULL, category TEXT, quantity INTEGER NOT NULL DEFAULT 0, unit_price NUMERIC NOT NULL DEFAULT 0, expiry_date TEXT, reorder_level INTEGER DEFAULT 10, supplier TEXT, status TEXT DEFAULT 'AVAILABLE');
CREATE TABLE IF NOT EXISTS equipment (equipment_id INTEGER PRIMARY KEY AUTOINCREMENT, equipment_name TEXT NOT NULL, department_id INTEGER, quantity INTEGER NOT NULL DEFAULT 1, equipment_condition TEXT, status TEXT DEFAULT 'AVAILABLE', last_maintenance_date TEXT, next_maintenance_date TEXT, FOREIGN KEY (department_id) REFERENCES departments(department_id));
CREATE TABLE IF NOT EXISTS doctor_availability (availability_id INTEGER PRIMARY KEY AUTOINCREMENT, doctor_id INTEGER NOT NULL, day_of_week TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id));
CREATE TABLE IF NOT EXISTS triage_assessments (triage_id INTEGER PRIMARY KEY AUTOINCREMENT, emergency_id INTEGER NOT NULL, patient_id INTEGER NOT NULL, symptoms TEXT, condition_description TEXT, vital_signs TEXT, priority TEXT NOT NULL, risk_score INTEGER NOT NULL, confidence_score INTEGER NOT NULL, recommended_action TEXT, ai_reasoning TEXT, human_review_status TEXT NOT NULL DEFAULT 'PENDING', reviewed_by INTEGER, reviewed_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (emergency_id) REFERENCES emergency_cases(emergency_id), FOREIGN KEY (patient_id) REFERENCES patients(patient_id), FOREIGN KEY (reviewed_by) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS bed_allocations (allocation_id INTEGER PRIMARY KEY AUTOINCREMENT, bed_id INTEGER NOT NULL, patient_id INTEGER NOT NULL, emergency_id INTEGER, bed_type TEXT, priority TEXT NOT NULL DEFAULT 'MEDIUM', match_score INTEGER NOT NULL DEFAULT 0, confidence_score INTEGER NOT NULL DEFAULT 0, reason TEXT, factors TEXT, status TEXT NOT NULL DEFAULT 'RECOMMENDED', human_review_status TEXT NOT NULL DEFAULT 'PENDING', reviewed_by INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP, released_at TEXT, FOREIGN KEY (bed_id) REFERENCES beds(bed_id), FOREIGN KEY (patient_id) REFERENCES patients(patient_id), FOREIGN KEY (emergency_id) REFERENCES emergency_cases(emergency_id), FOREIGN KEY (reviewed_by) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS doctor_workload (workload_id INTEGER PRIMARY KEY AUTOINCREMENT, doctor_id INTEGER NOT NULL, workload_date TEXT NOT NULL, active_appointments INTEGER NOT NULL DEFAULT 0, emergency_cases INTEGER NOT NULL DEFAULT 0, total_patients INTEGER NOT NULL DEFAULT 0, workload_score INTEGER NOT NULL DEFAULT 0, availability_status TEXT NOT NULL DEFAULT 'AVAILABLE', suggested_for_emergency INTEGER NOT NULL DEFAULT 1, computed_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE (doctor_id, workload_date), FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id));
CREATE TABLE IF NOT EXISTS medicine_predictions (prediction_id INTEGER PRIMARY KEY AUTOINCREMENT, medicine_id INTEGER NOT NULL, current_quantity INTEGER NOT NULL DEFAULT 0, estimated_daily_usage INTEGER NOT NULL DEFAULT 0, days_remaining INTEGER NOT NULL DEFAULT 0, shortage_risk TEXT NOT NULL DEFAULT 'LOW', predicted_shortage_date TEXT, expiry_risk INTEGER NOT NULL DEFAULT 0, recommended_reorder_quantity INTEGER NOT NULL DEFAULT 0, confidence_score INTEGER NOT NULL DEFAULT 50, recommendation TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (medicine_id) REFERENCES medicines(medicine_id));
CREATE TABLE IF NOT EXISTS ai_agent_logs (log_id INTEGER PRIMARY KEY AUTOINCREMENT, agent_id TEXT NOT NULL, agent_name TEXT NOT NULL, event_type TEXT NOT NULL DEFAULT 'info', message TEXT NOT NULL, reference_type TEXT, reference_id TEXT, confidence_score INTEGER, created_by INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (created_by) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS simulations (simulation_id INTEGER PRIMARY KEY AUTOINCREMENT, scenario_name TEXT NOT NULL, scenario_key TEXT NOT NULL, parameters TEXT, ran_by INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (ran_by) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS simulation_results (result_id INTEGER PRIMARY KEY AUTOINCREMENT, simulation_id INTEGER NOT NULL, bed_demand INTEGER NOT NULL DEFAULT 0, icu_demand INTEGER NOT NULL DEFAULT 0, doctor_workload_delta INTEGER NOT NULL DEFAULT 0, medicine_demand_units INTEGER NOT NULL DEFAULT 0, ambulances_required INTEGER NOT NULL DEFAULT 0, capacity_risk TEXT NOT NULL DEFAULT 'LOW', predicted_state TEXT, recommendations TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (simulation_id) REFERENCES simulations(simulation_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS outcome_verifications (outcome_id INTEGER PRIMARY KEY AUTOINCREMENT, emergency_id INTEGER, appointment_id INTEGER, patient_id INTEGER NOT NULL, outcome TEXT NOT NULL DEFAULT 'STABLE', status TEXT NOT NULL DEFAULT 'OPEN', follow_up_date TEXT, verification TEXT, notes TEXT, reviewer_id INTEGER, verified_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (emergency_id) REFERENCES emergency_cases(emergency_id), FOREIGN KEY (appointment_id) REFERENCES appointments(appointment_id), FOREIGN KEY (patient_id) REFERENCES patients(patient_id), FOREIGN KEY (reviewer_id) REFERENCES users(user_id));

